package functions

import (
	"bufio"
	"bytes"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"host-panel-api/internal/composekit"
)

// Credentials are the invoke credentials of a function, generated by the
// panel and returned once (creation, rotation), then forgotten:
//   - a bearer token: only its SHA-256 reaches the container
//     (LOCH_RUNTIME_TOKEN_SHA256): every variable of the container is
//     readable by the function code (same uid, /proc/<pid>/environ of the
//     exec'd processes), the hash lets it check a token, not forge one;
//   - optionally (Reference.SigV4, off by default) a SigV4 static key pair
//     for AWS SDK callers: the runtime needs the secret itself
//     (LOCH_RUNTIME_ACCESS_KEY), so the function code can read it; it only
//     lets the function invoke itself.
//
// The access key id is random too and treated as sensitive (never logged).
// Loopback callers (the panel's docker exec invoke, the healthcheck) need
// no credential.
type Credentials struct {
	Token           string `json:"token"`
	AccessKeyID     string `json:"accessKeyId,omitempty"`
	SecretAccessKey string `json:"secretAccessKey,omitempty"`
	// Endpoint is the Invoke URL for the members of the function's
	// networks (AWS SDKs: endpoint-url http://fn-<name>:8080, region
	// us-east-1).
	Endpoint string `json:"endpoint"`
	Region   string `json:"region"`
}

// String never prints the values.
func (c Credentials) String() string { return "Credentials{[redacted]}" }

// GoString never prints the values.
func (c Credentials) GoString() string { return c.String() }

const (
	accessKeyIDLen     = 20
	accessKeyAlphabet  = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
	tokenBytes         = 32 // 43 characters, base64url
	secretKeyBytes     = 30 // 40 characters, base64url
	runtimeInvokePort  = "8080"
	invokePathTemplate = "/2015-03-31/functions/%s/invocations"
)

// randomString draws n characters of alphabet uniformly (rejection
// sampling) from crypto/rand.
func randomString(n int, alphabet string) (string, error) {
	limit := 256 - 256%len(alphabet)
	out := make([]byte, 0, n)
	buf := make([]byte, 2*n)
	for len(out) < n {
		if _, err := rand.Read(buf); err != nil {
			return "", err
		}
		for _, b := range buf {
			if int(b) < limit && len(out) < n {
				out = append(out, alphabet[int(b)%len(alphabet)])
			}
		}
	}
	return string(out), nil
}

func randomBase64(n int) (string, error) {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b), nil
}

// newCredentials generates the invoke credentials of a function (a SigV4
// key pair only when sigv4).
func newCredentials(n Name, sigv4 bool) (*Credentials, error) {
	token, err := randomBase64(tokenBytes)
	if err != nil {
		return nil, err
	}
	c := &Credentials{
		Token:    token,
		Endpoint: "http://" + n.Project() + ":" + runtimeInvokePort + fmt.Sprintf(invokePathTemplate, n.String()),
		Region:   defaultRegion,
	}
	if sigv4 {
		if c.AccessKeyID, err = randomString(accessKeyIDLen, accessKeyAlphabet); err != nil {
			return nil, err
		}
		if c.SecretAccessKey, err = randomBase64(secretKeyBytes); err != nil {
			return nil, err
		}
	}
	return c, nil
}

// renderCredentialsEnv renders the env_file of the invoke credentials
// (format: raw, sorted): the SHA-256 of the token, never the token, and
// the SigV4 key pair when enabled.
func renderCredentialsEnv(c *Credentials) []byte {
	sum := sha256.Sum256([]byte(c.Token))
	var b strings.Builder
	if c.AccessKeyID != "" {
		b.WriteString(envAccessKey + "=" + c.AccessKeyID + ":" + c.SecretAccessKey + "\n")
	}
	b.WriteString(envTokenSHA256 + "=" + hex.EncodeToString(sum[:]) + "\n")
	return []byte(b.String())
}

// Variables of CredentialsEnvFile (the runtime's).
const (
	envTokenSHA256 = "LOCH_RUNTIME_TOKEN_SHA256"
	envAccessKey   = "LOCH_RUNTIME_ACCESS_KEY"
)

// CredentialEnvNames are the variables of the credentials env_file of a
// reference.
func CredentialEnvNames(ref *Reference) []string {
	if ref.SigV4 {
		return []string{envAccessKey, envTokenSHA256}
	}
	return []string{envTokenSHA256}
}

// parseEnvFile reads a raw env_file written by the panel (NAME=value per
// line). Values are never part of an error.
func parseEnvFile(data []byte) (map[string]string, error) {
	out := map[string]string{}
	sc := bufio.NewScanner(bytes.NewReader(data))
	sc.Buffer(make([]byte, 0, 8<<10), 2*maxEnvValue)
	line := 0
	for sc.Scan() {
		line++
		k, v, ok := strings.Cut(sc.Text(), "=")
		if !ok || ValidateEnvName(k, "secrets") != nil {
			return nil, fmt.Errorf("env file: invalid line %d", line)
		}
		if _, dup := out[k]; dup {
			return nil, fmt.Errorf("env file: duplicate variable on line %d", line)
		}
		out[k] = v
	}
	if err := sc.Err(); err != nil {
		return nil, fmt.Errorf("env file: %w", err)
	}
	return out, nil
}

// ReadSecretsEnv returns the secret values of a function (never logged nor
// returned to a client: used to rewrite the env_file).
func (p Paths) ReadSecretsEnv(n Name) (map[string]string, error) {
	if err := p.privateDirs(n); err != nil {
		return nil, err
	}
	data, err := composekit.ReadFileNoFollow(p.SecretsEnv(n))
	if err != nil {
		return nil, err
	}
	return parseEnvFile(data)
}

// writePrivateFile writes a file of the private directory atomically.
func (p Paths) writePrivateFile(n Name, name string, data []byte, perm os.FileMode) error {
	if err := p.privateDirs(n); err != nil {
		return err
	}
	return composekit.WriteFileAtomic(p.Private(n), filepath.Base(name), data, perm)
}
